 document.body.append(dlg);const liveStatus=document.createElement('p');liveStatus.id='pl-live-status';liveStatus.className='notice';liveStatus.setAttribute('role','status');dlg.querySelector('.pl-canvas').append(liveStatus);const el=id=>document.getElementById('pl-'+id),paramKeys=['captureMode','corridorWidth','poiReference','poiOffset','spacingMode','photoDistance','trackDistance','frontOverlap','sideOverlap','height','ground','bottom','top','standoff','radius','targetHeight','bearing','speed','photoPause','photoLimit','sectionOverlap','wallSide','shape','terrainMode','terrainDataset','startLat','startLng','terrainStep','terrainMargin','maxClimbSpeed','turnDirection','turns','pitchMode','cameraPitch'];
