 function drawHeightProfile(ctx){const result=lastPreview;const pts=result.points;let length=0;const ds=pts.map((p,i)=>{if(i&&!p.breakBefore){const a=pts[i-1],dy=(p.lat-a.lat)*111319,dx=(p.lng-a.lng)*111319*Math.cos(p.lat*Math.PI/180);length+=Math.hypot(dx,dy);}return length;});const min=Math.min(0,...pts.map(p=>p.groundHeight??0)),max=Math.max(result.heightFloor?.minimum||0,...pts.map(p=>p.height)),x=d=>70+d/Math.max(1,length)*970,y=z=>570-(z-min)/Math.max(1,max-min)*470;ctx.strokeStyle='#83a098';ctx.fillStyle='#d6e5df';ctx.font='18px sans-serif';for(let i=0;i<=5;i++){const z=min+(max-min)*i/5;ctx.beginPath();ctx.moveTo(70,y(z));ctx.lineTo(1040,y(z));ctx.stroke();ctx.fillText(z.toFixed(0)+' m',10,y(z)+5);}ctx.fillStyle='#375b44';ctx.beginPath();ctx.moveTo(x(0),570);pts.forEach((p,i)=>ctx.lineTo(x(ds[i]),y(p.groundHeight??0)));ctx.lineTo(x(length),570);ctx.closePath();ctx.fill();ctx.strokeStyle='#f1ca53';ctx.lineWidth=3;ctx.beginPath();pts.forEach((p,i)=>{if(!i||p.breakBefore)ctx.moveTo(x(ds[i]),y(p.height));else ctx.lineTo(x(ds[i]),y(p.height));});ctx.stroke();if(result.heightFloor){ctx.strokeStyle='#ffaf76';ctx.setLineDash([8,5]);ctx.beginPath();ctx.moveTo(70,y(result.heightFloor.minimum));ctx.lineTo(1040,y(result.heightFloor.minimum));ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#ffaf76';ctx.font='16px sans-serif';ctx.fillText('Mindesthöhe '+result.heightFloor.minimum.toFixed(1)+' m',75,y(result.heightFloor.minimum)-8);}ctx.fillStyle='#fff';ctx.font='22px sans-serif';ctx.fillText(result.name+' · Höhenprofil',25,35);ctx.font='17px sans-serif';ctx.fillText('0 m',70,605);ctx.fillText((length/1000).toFixed(2)+' km',930,605);ctx.fillText(result.terrain?'Grün: DEM relativ Start · Gelb: Flugroute · Abschnittslücken ohne Verbindung':'Ohne DEM: ebene Bezugshöhe · Gelb: Flugroute',25,640);}
