 async function updateDrafts(){const r=await api('planner-list');el('drafts').replaceChildren(new Option('Neue Planung',''));for(const d of r.plans)el('drafts').append(new Option((pathFor(d.folder)||'Ohne Projekt')+' / '+d.name,d.id));el('drafts').value=draftId;}
