 const ranges={corridorWidth:[1,200,1],photoDistance:[.5,100,.5],trackDistance:[.5,100,.5],frontOverlap:[10,95,1],sideOverlap:[10,95,1],height:[1,150,1],ground:[-100,100,1],bottom:[1,150,1],top:[1,200,1],standoff:[2,200,1],radius:[0,300,1],targetHeight:[-50,150,1],bearing:[-180,360,1],speed:[.2,15,.1],photoPause:[0,30,1],photoLimit:[20,200,1],sectionOverlap:[0,10,1],terrainStep:[5,30,1],terrainMargin:[0,50,1],maxClimbSpeed:[.2,5,.1],turns:[0,30,1],cameraPitch:[-90,30,1]};
 for(const [key,range] of Object.entries(ranges)){const number=el(key),slider=document.createElement('input');slider.type='range';slider.id='pl-slider-'+key;[slider.min,slider.max,slider.step]=range.map(String);slider.setAttribute('aria-label',number.parentElement.textContent.trim());slider.className='pl-slider';number.before(slider);slider.oninput=()=>{number.value=slider.value;number.dispatchEvent(new Event('input',{bubbles:true}));};}
