 function renderHeightReference(){el('height-settings').hidden=!heightReference;el('height-file').value='';if(!heightReference){el('height-list').replaceChildren();drawHeightMarkers();return;}el('height-source').textContent=heightReference.name+' · '+heightReference.points.length+' Punkte · relativ zum Quellstart';el('height-datum').value=heightReference.datum;el('height-offset').value=heightReference.datumOffset;el('height-margin').value=heightReference.margin;el('height-enabled').checked=heightReference.enabled;el('height-list').replaceChildren();heightReference.points.forEach((p,i)=>{const label=document.createElement('label'),check=document.createElement('input');check.type='checkbox';check.checked=p.selected;check.setAttribute('aria-label','Höhenpunkt '+(i+1));check.onchange=()=>{p.selected=check.checked;refreshHeightReference();};label.append(check,document.createTextNode(`H${i+1} · ${p.height.toFixed(1)} m`));el('height-list').append(label);});refreshHeightReference(false);}
