 function heightArchiveOptions(){const missions=data.missions.filter(m=>sourceType(m)==='KMZ');const label=m=>(pathList(m.folder).map(f=>f.name).join(' / ')||'Ohne Projekt')+' / '+m.name+(m.archived?' · archiviert':'');missions.sort((a,b)=>label(a).localeCompare(label(b),'de'));el('height-archive').replaceChildren(new Option(missions.length?'Archivmission auswählen …':'Keine DJI-KMZ im zugänglichen Archiv',''),...missions.map(m=>new Option(label(m),m.id)));el('height-archive-load').disabled=true;}
