 const optionsButton=document.createElement('button');optionsButton.type='button';optionsButton.className='btn btn-icon';optionsButton.id='pl-options-toggle';optionsButton.innerHTML=ICON.sidebar;optionsButton.title='Seitenleiste ein-/ausblenden';optionsButton.setAttribute('aria-label','Seitenleiste ein-/ausblenden');optionsButton.setAttribute('aria-expanded','true');optionsButton.onclick=()=>{const hidden=dlg.classList.toggle('pl-options-hidden');optionsButton.setAttribute('aria-expanded',String(!hidden));map?.invalidateSize();};dlg.querySelector('.pl-view-tools').append(optionsButton);
 const crossLabel=document.createElement('label');crossLabel.className='pl-compact-check pl-top-check';crossLabel.title='Zwei vollständige Rasterdurchgänge mit 90° Unterschied als getrennte Abschnitte';crossLabel.innerHTML='<input type="checkbox" id="pl-cross-grid"> Kreuzraster';topTools.append(crossLabel);el('cross-grid').onchange=invalidate;
 function alignLongest(change=true){if(geometry?.type!=='Polygon')return;const ring=geometry.coordinates[0];let longest=-1,angle=0;for(let i=1;i<ring.length;i++){const a=ring[i-1],b=ring[i],x=(b[0]-a[0])*Math.cos((a[1]+b[1])*Math.PI/360),y=b[1]-a[1],d=x*x+y*y;if(d>longest){longest=d;angle=(Math.atan2(x,y)*180/Math.PI+180)%180;}}el('bearing').value=angle.toFixed(1);syncSliders();if(change){invalidate();syncSliders();}}
