 function drawFootprint(){footprintGroup?.clearLayers();if(!result||!footprintPoint||fp.getAttribute('aria-pressed')!=='true')return;const r=result,p=footprintPoint;if(r.terrain){status('Footprint: derzeit nur ebene Aufnahmefläche, kein DEM-Oberflächenschnitt.');return;}const c=r.camera,diag=Math.tan(c.fov*Math.PI/360),norm=Math.hypot(c.w,c.h),tx=diag*c.w/norm,ty=diag*c.h/norm,down=-p.pitch*Math.PI/180,yaw=p.yaw*Math.PI/180,h=p.height-r.params.ground;if(h<=0)return;const corners=[];for(const [u,v] of [[-tx,-ty],[tx,-ty],[tx,ty],[-tx,ty]]){const dz=Math.sin(down)-v*Math.cos(down);if(dz<=.001){status('Footprint reicht bis zum Horizont: keine endliche Bodenprojektion.');return;}const forward=(Math.cos(down)+v*Math.sin(down))*h/dz,right=u*h/dz,x=forward*Math.sin(yaw)+right*Math.cos(yaw),y=forward*Math.cos(yaw)-right*Math.sin(yaw);if(Math.hypot(x,y)>10000){status('Footprint außerhalb des Darstellungsbereichs.');return;}corners.push([p.lat+y/111319.49079327358,p.lng+x/(111319.49079327358*Math.cos(p.lat*Math.PI/180))]);}L.polygon(corners,{color:'#8557c7',weight:2,fillOpacity:.12,interactive:false,pmIgnore:true}).addTo(footprintGroup);status('Footprint auf ebener Aufnahmefläche · anderen Fotopunkt anklicken.');}
